    radarOrigin.y = mapY - 8;

    if (radarOrigin.x < -9)
        radarOrigin.x = -9;
    if (radarOrigin.y < -8)
        radarOrigin.y = -8;
    if (radarOrigin.x > gMapWidth - 10)
        radarOrigin.x = gMapWidth - 10;
    if (radarOrigin.y > gMapHeight - 9)
        radarOrigin.y = gMapHeight - 9;

