    gpSoundManager->SwitchAmbientMusic(gTerrainMusicIds[field_58]);
    SetEnvironmentOrigin(center, 1);
    seedingValid = 0;

    if (gpCurrentPlayer->IsLocalHuman() && gpCurrentPlayer->HasMobileHero())
        advWindow->WidgetClearStatus(11, 0x4008);
